/*
 * FFU (Flow Filter Unit) initialization sequence for the FM6000 on the
 * Arista 7150S-52.
 *
 * Data recovered from a running 7150S-52 with OSPF active (2026-08-07),
 * validated by EdgeNOS (feature/arista-7150-fm6000).  Includes all 14,549
 * writes in original order: single-write table entries AND the multi-write
 * shadow registers that implement the FFU_ATOMIC_APPLY strobes (0x3f0000,
 * written 59 times alternating 0x1/0x2).  Collapsing those destroys the
 * commit pulse and renders the TCAM entries invisible.
 *
 * Called from pipeline_init() after every RESET_N (ring-reinit) wipes the
 * FFU TCAM.  Without this call received frames are never punted to the CPU
 * and rx_frames stays at 0.
 */
#include "ffu.h"
#include "pci.h"
#include <fcntl.h>
#include <stdio.h>
#include <string.h>
#include <unistd.h>

static void ffu_kmsg(const char *msg)
{
	int fd = open("/dev/kmsg", O_WRONLY | O_NOCTTY);
	if (fd >= 0) {
		write(fd, msg, strlen(msg));
		write(fd, "\n", 1);
		close(fd);
	}
	fprintf(stderr, "%s\n", msg);
}

