#define FFU_SEQ_LEN (sizeof(ffu_seq)/sizeof(ffu_seq[0]))

int fm_ffu_init(struct fm6000 *d)
{
	unsigned i;

	ffu_kmsg("nosd-fm6000: FFU init start");
	/* check_writes stays ON (default 1): each fm_wr() does a PCIe config read
	 * after the write to drain the posted-write buffer and detect chip dropout.
	 * Disabling check_writes lets posted writes accumulate in the Root Complex
	 * PWB; if the FM6000 self-resets during the bulk write the CPU stalls on
	 * the next write to a full PWB — this cannot be caught by a periodic
	 * offbus check because the stall precedes the check. */
	for (i = 0; i < FFU_SEQ_LEN; i++) {
		int rv = fm_wr(d, ffu_seq[i][0], ffu_seq[i][1]);
		if (rv != FM_OK) {
			fprintf(stderr, "nosd-fm6000: FFU init failed at entry %u addr=0x%x rv=%d\n",
				i, ffu_seq[i][0], rv);
			return rv;
		}
	}
	ffu_kmsg("nosd-fm6000: FFU init done");
	return FM_OK;
}
